import os,re

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G=load()
print("Grids loaded:", sorted(G.keys()))
for k,v in sorted(G.items()):
    print(f"\n{k}: {v}")

import numpy as np

def apply_transformation(grid):
    """Copy each non-zero component to position (r+5, c+3)"""
    rows, cols = len(grid), len(grid[0])

    # Create a set of visited positions
    visited = set()
    new_grid = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and (r, c) not in visited:
                # This is a new connected component; find all connected cells
                component = []
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    curr_r, curr_c = stack.pop()
                    component.append((curr_r, curr_c))

                    # Check 4-connected neighbors
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == grid[curr_r][curr_c] and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))

                # Copy this component to new position
                for orig_r, orig_c in component:
                    val = grid[orig_r][orig_c]
                    new_r = orig_r + 5
                    new_c = orig_c + 3
                    if 0 <= new_r < rows and 0 <= new_c < cols:
                        new_grid[new_r][new_c] = val

    return new_grid

