                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 0 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                if len(comp) == 1:
                    small_positions.add(comp[0])
                else:
                    components.append(comp)

    # Start fresh
    result = [[0]*cols for _ in range(rows)]

    # Step 1: Add originals for large components only
    for comp in components:
        for r, c in comp:
            result[r][c] = grid[r][c]

